## Code Example

```javascript
// Minimal concurrency-limited debounced fetch per field using closures
function createFieldController(fetchUrl, maxConcurrent = 4) {
  let debounceTimer;
  let abortController;

  return {
    onInput: async (term) => {
      // Cancel previous request
      if (abortController) {
        abortController.abort();
      }

      // Clear existing debounce
      clearTimeout(debounceTimer);

      // Set new debounce
      debounceTimer = setTimeout(async () => {
        // Check global concurrency limit
        if (globalInFlight >= maxConcurrent) {
          await waitForSlot();
        }

        globalInFlight++;
        abortController = new AbortController();

        try {
          const response = await fetch(`${fetchUrl}?q=${term}`, {
            signal: abortController.signal
          });

          if (!abortController.signal.aborted) {
            const suggestions = await response.json();
            updateFieldUI(suggestions);
          }
        } catch (error) {
          if (error.name !== 'AbortError') {
            console.error('Fetch error:', error);
          }
        } finally {
          globalInFlight--;
        }
      }, 300);
    }
  };
}
```

## Why This Is Asked
This question evaluates understanding of closures, Promise deduplication, request cancellation, and caching strategies in building a production-ready fetch helper. It also touches on memory management with LRU caches and handling abortable requests.

## Key Concepts
- Closures for per-key state isolation
- Promise deduplication to prevent redundant network requests
- Cancellation with AbortController for stale requests
- LRU cache implementation using Map for ordered storage
- Edge cases: rapid toggling between keys and stale data handling

## Code Example
```javascript
const api = (() => {
  const inFlight = new Map();
  const cache = new Map();
  const MAX_CACHE = 50;

  function memoFetch(key, options = {}) {
    if (cache.has(key)) {
      const entry = cache.get(key);
      cache.delete(key);
      cache.set(key, entry);
      return Promise.resolve(entry);
    }

    if (inFlight.has(key)) {
      return inFlight.get(key);
    }

    const controller = new AbortController();
    const promise = fetch(key, { ...options, signal: controller.signal })
      .then(res => res.json())
      .then(data => {
        inFlight.delete(key);
        if (cache.size >= MAX_CACHE) {
          const firstKey = cache.keys().next().value;
          cache.delete(firstKey);
        }
        cache.set(key, data);
        return data;
      })
      .catch(err => {
        inFlight.delete(key);
        throw err;
      });

    inFlight.set(key, { promise, controller });
    return promise;
  }

  function cancel(key) {
    if (inFlight.has(key)) {
      inFlight.get(key).controller.abort();
      inFlight.delete(key);
    }
  }

  return { memoFetch, cancel };
})();
```

